from pathlib import Path
p=Path('index.html');s=p.read_text(encoding='utf-8');s=s.replace('<h3>События и компании</h3>','<h2>События и компании</h2>').replace('<h3>Еда с собой</h3>','<h2>Еда с собой</h2>');p.write_text(s,encoding='utf-8')
p=Path('README.md');s=p.read_text(encoding='utf-8');s=s.replace('Публикация выполняется по запросу пользователя в репозиторий','Публикация отложена по просьбе пользователя. Для будущего размещения выбран репозиторий');s+='\n## Текущие правки\n\nВ четвёртой редакции обновлены первый экран и навигация. Галерея содержит четыре фото, включая веранду. В меню максимум три колонки и одинаковая ширина одиночных карточек; кнопка «Показать меньше» возвращает категорию к четырём блюдам. Футер и короткие переходы удалены, добавлена фиксированная кнопка наверх. Контакты расположены перед адресом и часами работы, карта завершает страницу. Для двух супов исходные снимки 3333 × 5000 уменьшены до 1000 × 1500 с сохранением пропорций.\n';p.write_text(s,encoding='utf-8')
